begin;
-- Recovered Aura workflow, shared memory. Quotations only: no accounting writes.
create table public.b2b_catalogo_reglas (
 proveedor_id uuid not null references public.proveedores(id), referencia_key text not null,
 referencia_original text not null, producto_id uuid not null references public.productos(id),
 margen numeric(16,2) not null default 20000, motivo text not null default '',
 creado_por uuid not null references public.perfiles(id), actualizado_at timestamptz not null default now(),
 primary key(proveedor_id,referencia_key), check(length(referencia_key) between 1 and 500),
 check(margen::text not in ('NaN','Infinity','-Infinity')),
 check(margen=20000 or length(btrim(motivo))>0)
);
create index b2b_catalogo_reglas_producto on public.b2b_catalogo_reglas(producto_id);
create index b2b_catalogo_reglas_autor on public.b2b_catalogo_reglas(creado_por);
create table public.b2b_catalogo_borradores (
 id uuid primary key default gen_random_uuid(), proveedor_id uuid not null references public.proveedores(id),
 texto_original text not null check(length(texto_original) between 1 and 200000),
 filas jsonb not null check(jsonb_typeof(filas)='array' and jsonb_array_length(filas) between 1 and 5000),
 creado_por uuid not null references public.perfiles(id), creado_at timestamptz not null default now(),
 lista_id uuid references public.b2b_listas_precios(id)
);
create index b2b_catalogo_borradores_proveedor on public.b2b_catalogo_borradores(proveedor_id,creado_at desc);
create index b2b_catalogo_borradores_autor on public.b2b_catalogo_borradores(creado_por);
create index b2b_catalogo_borradores_lista on public.b2b_catalogo_borradores(lista_id);
alter table public.b2b_catalogo_reglas enable row level security;
alter table public.b2b_catalogo_borradores enable row level security;
revoke all on public.b2b_catalogo_reglas,public.b2b_catalogo_borradores from public,anon,authenticated;
grant select on public.b2b_catalogo_reglas,public.b2b_catalogo_borradores to authenticated;
create policy reglas_admin on public.b2b_catalogo_reglas for select to authenticated using(exists(select 1 from public.perfiles where id=(select auth.uid()) and activo and rol in ('gerencia','auditoria')));
create policy borradores_admin on public.b2b_catalogo_borradores for select to authenticated using(exists(select 1 from public.perfiles where id=(select auth.uid()) and activo and rol in ('gerencia','auditoria')));

create function public.guardar_regla_catalogo_b2b(p_proveedor uuid,p_referencia text,p_producto uuid,p_margen numeric default 20000,p_motivo text default '')
returns void language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.perfiles where id=auth.uid() and activo and rol in ('gerencia','auditoria')) then raise exception 'Solo administración puede confirmar equivalencias';end if;
 if not exists(select 1 from public.productos where id=p_producto and activo) or not exists(select 1 from public.proveedores where id=p_proveedor and activo) then raise exception 'Referencia o proveedor inactivo';end if;
 -- Same conservative normalization as the client, preserving RAM/storage/connectivity.
 insert into public.b2b_catalogo_reglas(proveedor_id,referencia_key,referencia_original,producto_id,margen,motivo,creado_por)
 values(p_proveedor,upper(regexp_replace(btrim(translate(p_referencia,'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')),'\s+',' ','g')),p_referencia,p_producto,p_margen,coalesce(p_motivo,''),auth.uid())
 on conflict(proveedor_id,referencia_key) do update set producto_id=excluded.producto_id,margen=excluded.margen,motivo=excluded.motivo,creado_por=auth.uid(),actualizado_at=now();
end $$;

create function public.guardar_borrador_catalogo_b2b(p_proveedor uuid,p_texto text,p_filas jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 if not exists(select 1 from public.perfiles where id=auth.uid() and activo and rol in ('gerencia','auditoria')) then raise exception 'Solo administración puede guardar listas';end if;
 if not exists(select 1 from public.proveedores where id=p_proveedor and activo) then raise exception 'Proveedor inactivo';end if;
 insert into public.b2b_catalogo_borradores(proveedor_id,texto_original,filas,creado_por) values(p_proveedor,p_texto,p_filas,auth.uid()) returning id into v_id;
 return v_id;
end $$;

create function public.publicar_borrador_catalogo_b2b(p_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d public.b2b_catalogo_borradores%rowtype; v_rows jsonb; v_result jsonb;
begin
 if not exists(select 1 from public.perfiles where id=auth.uid() and activo and rol in ('gerencia','auditoria')) then raise exception 'Solo administración puede publicar listas';end if;
 select * into d from public.b2b_catalogo_borradores where id=p_id for update;
 if not found then raise exception 'Borrador no encontrado';end if;
 if d.lista_id is not null then return jsonb_build_object('id',d.lista_id,'repetida',true);end if;
 if exists(select 1 from jsonb_array_elements(d.filas) f where coalesce((f->>'included')::boolean,false)=false and nullif(btrim(f->>'exclusion'),'') is null) then raise exception 'Explica las filas excluidas antes de publicar';end if;
 if exists(select 1 from jsonb_array_elements(d.filas) f where (f->>'included')::boolean and (f->>'proveedor_id')::uuid is distinct from d.proveedor_id) then raise exception 'El proveedor no corresponde al borrador';end if;
 select jsonb_agg(f) into v_rows from jsonb_array_elements(d.filas) f where (f->>'included')::boolean;
 v_result:=public.publicar_lista_b2b('WhatsApp · '||d.id,md5(d.id::text)||md5(d.id::text),'proveedores',v_rows);
 update public.b2b_catalogo_borradores set lista_id=(v_result->>'id')::uuid where id=d.id;
 return v_result;
end $$;
revoke all on function public.guardar_regla_catalogo_b2b(uuid,text,uuid,numeric,text),public.guardar_borrador_catalogo_b2b(uuid,text,jsonb),public.publicar_borrador_catalogo_b2b(uuid) from public,anon;
grant execute on function public.guardar_regla_catalogo_b2b(uuid,text,uuid,numeric,text),public.guardar_borrador_catalogo_b2b(uuid,text,jsonb),public.publicar_borrador_catalogo_b2b(uuid) to authenticated;
